import { describe, expect, it } from 'vitest';
import { loadWsdlImports, parseWsdlDocument, soapHeaders, wsdlCollectionName, wsdlNameFromUrl, wsdlRequests } from '../lib/wsdl';
import { detectImportSource } from '../lib/importSource';
import { parseXml } from '../lib/xml';

const calculator = `<?xml version="1.0" encoding="utf-8"?>
<!-- generated by a SOAP stack -->
<wsdl:definitions xmlns:wsdl="http://schemas.xmlsoap.org/wsdl/"
    xmlns:soap="http://schemas.xmlsoap.org/wsdl/soap/"
    xmlns:soap12="http://schemas.xmlsoap.org/wsdl/soap12/"
    xmlns:s="http://www.w3.org/2001/XMLSchema"
    xmlns:calc="http://example.com/calc"
    targetNamespace="http://example.com/calc">
  <wsdl:documentation>Adds &amp; checks numbers.</wsdl:documentation>
  <wsdl:types>
    <s:schema elementFormDefault="qualified" targetNamespace="http://example.com/calc">
      <s:simpleType name="Mode">
        <s:restriction base="s:string">
          <s:enumeration value="Fast"/>
          <s:enumeration value="Exact"/>
        </s:restriction>
      </s:simpleType>
      <s:complexType name="Operand">
        <s:sequence>
          <s:element name="value" type="s:int"/>
          <s:element minOccurs="0" name="label" type="s:string"/>
        </s:sequence>
        <s:attribute name="unit" type="s:string" default="cm"/>
      </s:complexType>
      <s:complexType name="NamedOperand">
        <s:complexContent>
          <s:extension base="calc:Operand">
            <s:sequence>
              <s:element name="name" type="s:string"/>
            </s:sequence>
          </s:extension>
        </s:complexContent>
      </s:complexType>
      <s:complexType name="Tree">
        <s:sequence>
          <s:element minOccurs="0" maxOccurs="unbounded" name="child" type="calc:Tree"/>
        </s:sequence>
      </s:complexType>
      <s:element name="Add">
        <s:complexType>
          <s:sequence>
            <s:element name="a" type="calc:Operand"/>
            <s:element name="b" type="calc:NamedOperand"/>
            <s:element name="mode" type="calc:Mode"/>
            <s:element name="at" type="s:dateTime"/>
            <s:choice>
              <s:element name="round" type="s:boolean"/>
              <s:element name="precision" type="s:int"/>
            </s:choice>
            <s:element name="tree" type="calc:Tree"/>
          </s:sequence>
        </s:complexType>
      </s:element>
      <s:element name="AddResponse">
        <s:complexType><s:sequence><s:element name="AddResult" type="s:int"/></s:sequence></s:complexType>
      </s:element>
      <s:element name="Auth">
        <s:complexType><s:sequence><s:element name="token" type="s:string"/></s:sequence></s:complexType>
      </s:element>
      <s:element name="Ping"><s:complexType/></s:element>
    </s:schema>
  </wsdl:types>
  <wsdl:message name="AddSoapIn"><wsdl:part name="parameters" element="calc:Add"/></wsdl:message>
  <wsdl:message name="AddSoapOut"><wsdl:part name="parameters" element="calc:AddResponse"/></wsdl:message>
  <wsdl:message name="AuthHeader"><wsdl:part name="Auth" element="calc:Auth"/></wsdl:message>
  <wsdl:message name="PingSoapIn"><wsdl:part name="parameters" element="calc:Ping"/></wsdl:message>
  <wsdl:portType name="CalculatorSoap">
    <wsdl:operation name="Add">
      <wsdl:documentation>Adds two operands.</wsdl:documentation>
      <wsdl:input message="calc:AddSoapIn"/>
      <wsdl:output message="calc:AddSoapOut"/>
    </wsdl:operation>
    <wsdl:operation name="Ping"><wsdl:input message="calc:PingSoapIn"/></wsdl:operation>
  </wsdl:portType>
  <wsdl:binding name="CalculatorSoap" type="calc:CalculatorSoap">
    <soap:binding transport="http://schemas.xmlsoap.org/soap/http"/>
    <wsdl:operation name="Add">
      <soap:operation soapAction="http://example.com/calc/Add" style="document"/>
      <wsdl:input>
        <soap:body use="literal"/>
        <soap:header message="calc:AuthHeader" part="Auth" use="literal"/>
      </wsdl:input>
    </wsdl:operation>
    <wsdl:operation name="Ping">
      <soap:operation soapAction="" style="document"/>
      <wsdl:input><soap:body use="literal"/></wsdl:input>
    </wsdl:operation>
  </wsdl:binding>
  <wsdl:binding name="CalculatorSoap12" type="calc:CalculatorSoap">
    <soap12:binding transport="http://schemas.xmlsoap.org/soap/http"/>
    <wsdl:operation name="Add">
      <soap12:operation soapAction="http://example.com/calc/Add" style="document"/>
      <wsdl:input><soap12:body use="literal"/></wsdl:input>
    </wsdl:operation>
  </wsdl:binding>
  <wsdl:binding name="CalculatorHttpGet" type="calc:CalculatorSoap">
    <http:binding xmlns:http="http://schemas.xmlsoap.org/wsdl/http/" verb="GET"/>
  </wsdl:binding>
  <wsdl:service name="Calculator">
    <wsdl:port name="CalculatorSoap" binding="calc:CalculatorSoap">
      <soap:address location="https://calc.example.com/calculator.asmx"/>
    </wsdl:port>
    <wsdl:port name="CalculatorSoap12" binding="calc:CalculatorSoap12">
      <soap12:address location="https://calc.example.com/calculator.asmx"/>
    </wsdl:port>
    <wsdl:port name="CalculatorHttpGet" binding="calc:CalculatorHttpGet">
      <http:address xmlns:http="http://schemas.xmlsoap.org/wsdl/http/" location="https://calc.example.com/calculator.asmx"/>
    </wsdl:port>
  </wsdl:service>
</wsdl:definitions>
`;

const rpc = `<definitions name="StockQuote" xmlns="http://schemas.xmlsoap.org/wsdl/"
    xmlns:soap="http://schemas.xmlsoap.org/wsdl/soap/"
    xmlns:xsd="http://www.w3.org/2001/XMLSchema"
    xmlns:tns="urn:stock" targetNamespace="urn:stock">
  <message name="GetQuoteRequest">
    <part name="symbol" type="xsd:string"/>
    <part name="count" type="xsd:int"/>
  </message>
  <portType name="QuotePort"><operation name="GetQuote"><input message="tns:GetQuoteRequest"/></operation></portType>
  <binding name="QuoteBinding" type="tns:QuotePort">
    <soap:binding style="rpc" transport="http://schemas.xmlsoap.org/soap/http"/>
    <operation name="GetQuote">
      <soap:operation soapAction="urn:stock#GetQuote"/>
      <input><soap:body use="encoded" namespace="urn:stock:quotes"/></input>
    </operation>
  </binding>
  <service name="QuoteService">
    <port name="QuotePort" binding="tns:QuoteBinding"><soap:address location="http://localhost:8080/quote"/></port>
  </service>
</definitions>`;

describe('XML parser', () => {
  it('resolves namespaces, entities, CDATA and self-closing tags', () => {
    const root = parseXml('<?xml version="1.0"?><!DOCTYPE a [<!ENTITY x "y">]><a:root xmlns:a="urn:a" xmlns="urn:d" k=\'1 &gt; 0\'><child/><![CDATA[<raw>]]>&#65;&#x42;</a:root>');
    expect(root).toMatchObject({ local: 'root', ns: 'urn:a', attrs: { k: '1 > 0' }, text: '<raw>AB' });
    expect(root.children[0]).toMatchObject({ local: 'child', ns: 'urn:d' });
  });

  it('reports the line of broken markup', () => {
    expect(() => parseXml('<a>\n<b>\n</a>')).toThrow('line 3');
    expect(() => parseXml('<a>')).toThrow('never closed');
    expect(() => parseXml('hello')).toThrow('no root element');
  });
});

describe('WSDL import', () => {
  it('builds SOAP 1.1 and 1.2 requests for each SOAP port and skips HTTP bindings', () => {
    const wsdl = parseWsdlDocument(calculator);
    expect(wsdl.operations.map(operation => `${operation.port}.${operation.name} ${operation.soapVersion}`)).toEqual([
      'CalculatorSoap.Add 1.1',
      'CalculatorSoap.Ping 1.1',
      'CalculatorSoap12.Add 1.2',
    ]);
    expect(wsdlCollectionName(wsdl, 'calculator.wsdl')).toBe('Calculator');
    expect(wsdl.documentation).toBe('Adds & checks numbers.');
  });

  it('writes a sample envelope from the schema', () => {
    const [add] = parseWsdlDocument(calculator).operations;
    expect(add.envelope).toBe(`<?xml version="1.0" encoding="utf-8"?>
<soap:Envelope xmlns:soap="http://schemas.xmlsoap.org/soap/envelope/" xmlns:calc="http://example.com/calc">
  <soap:Header>
    <calc:Auth>
      <calc:token>?</calc:token>
    </calc:Auth>
  </soap:Header>
  <soap:Body>
    <calc:Add>
      <calc:a unit="cm">
        <calc:value>0</calc:value>
        <!--Optional:-->
        <calc:label>?</calc:label>
      </calc:a>
      <calc:b unit="cm">
        <calc:value>0</calc:value>
        <!--Optional:-->
        <calc:label>?</calc:label>
        <calc:name>?</calc:name>
      </calc:b>
      <calc:mode>Fast</calc:mode>
      <calc:at>2026-01-01T00:00:00</calc:at>
      <!--Choice of: round, precision-->
      <calc:round>false</calc:round>
      <calc:tree>
        <!--Optional:-->
        <calc:child>
          <!--Optional:-->
          <calc:child/>
        </calc:child>
      </calc:tree>
    </calc:Add>
  </soap:Body>
</soap:Envelope>
`);
    const envelope = parseXml(add.envelope);
    expect(envelope.local).toBe('Envelope');
  });

  it('uses the SOAP 1.2 envelope and an empty body element for empty messages', () => {
    const [, ping, add12] = parseWsdlDocument(calculator).operations;
    expect(ping.envelope).toContain('<soap:Body>\n    <calc:Ping/>\n  </soap:Body>');
    expect(ping.envelope).toContain('<soap:Header/>');
    expect(add12.envelope).toContain('xmlns:soap="http://www.w3.org/2003/05/soap-envelope"');
  });

  it('wraps rpc parts in the operation element', () => {
    const wsdl = parseWsdlDocument(rpc);
    expect(wsdlCollectionName(wsdl, 'x.wsdl')).toBe('StockQuote');
    expect(wsdl.operations[0].envelope).toContain(`  <soap:Body>
    <tns:GetQuote>
      <symbol>?</symbol>
      <count>0</count>
    </tns:GetQuote>
  </soap:Body>`);
    expect(wsdl.operations[0].envelope).toContain('xmlns:tns="urn:stock:quotes"');
  });

  it('turns operations into POST requests with SOAP headers, grouped by port', () => {
    const requests = wsdlRequests(parseWsdlDocument(calculator), 'col', 'Calculator');
    expect(requests.map(request => [request.folderPath, request.name, request.method, request.url, request.bodyType])).toEqual([
      [['CalculatorSoap'], 'Add', 'POST', 'https://calc.example.com/calculator.asmx', 'xml'],
      [['CalculatorSoap'], 'Ping', 'POST', 'https://calc.example.com/calculator.asmx', 'xml'],
      [['CalculatorSoap12'], 'Add', 'POST', 'https://calc.example.com/calculator.asmx', 'xml'],
    ]);
    expect(requests[0].headers.map(row => [row.key, row.value])).toEqual([['Content-Type', 'text/xml; charset=utf-8'], ['SOAPAction', '"http://example.com/calc/Add"']]);
    expect(requests[2].headers.map(row => [row.key, row.value])).toEqual([['Content-Type', 'application/soap+xml; charset=utf-8; action="http://example.com/calc/Add"']]);
    expect(requests[0].requestNotes).toBe('Adds two operands.\n\nSOAP 1.1 · Calculator / CalculatorSoap');
    expect(wsdlRequests(parseWsdlDocument(rpc), 'col', 'Stock')[0].folderPath).toEqual([]);
  });

  it('sends an empty SOAPAction for SOAP 1.1 and omits the action for SOAP 1.2', () => {
    expect(soapHeaders('1.1', '').map(row => row.value)).toEqual(['text/xml; charset=utf-8', '""']);
    expect(soapHeaders('1.2', '').map(row => row.value)).toEqual(['application/soap+xml; charset=utf-8']);
  });

  it('explains what it cannot import', () => {
    expect(() => parseWsdlDocument('<description xmlns="http://www.w3.org/ns/wsdl"/>')).toThrow('WSDL 2.0 is not supported');
    expect(() => parseWsdlDocument('<definitions xmlns="http://schemas.xmlsoap.org/wsdl/"><import location="other.wsdl"/></definitions>')).toThrow('files this WSDL imports');
    expect(() => parseWsdlDocument('<root/>')).toThrow('WSDL 1.1');
  });

  it('is detected by extension or content', () => {
    expect(detectImportSource('calculator.wsdl', calculator)).toBe('wsdl');
    expect(detectImportSource('service.xml', rpc)).toBe('wsdl');
    expect(detectImportSource('Service.svc', calculator)).toBe('wsdl');
    expect(detectImportSource('notes.xml', '<notes/>')).toBeNull();
  });

  it('names a collection fetched from a URL', () => {
    expect(wsdlNameFromUrl('https://calc.example.com/calculator.asmx?wsdl')).toBe('calculator');
    expect(wsdlNameFromUrl('https://example.com/?wsdl')).toBe('example.com');
  });
});

const split = {
  root: `<wsdl:definitions name="Calculator" xmlns:wsdl="http://schemas.xmlsoap.org/wsdl/" xmlns:soap12="http://schemas.xmlsoap.org/wsdl/soap12/" xmlns:i0="urn:calc" xmlns:tns="http://tempuri.org/" targetNamespace="http://tempuri.org/">
  <wsdl:import namespace="urn:calc" location="Service.svc?wsdl=wsdl0"/>
  <wsdl:service name="Calculator">
    <wsdl:port name="WSHttpBinding_ICalculator" binding="i0:WSHttpBinding_ICalculator">
      <soap12:address location="https://svc.example.com/api/Service12.svc"/>
    </wsdl:port>
  </wsdl:service>
</wsdl:definitions>`,
  defs: `<wsdl:definitions xmlns:wsdl="http://schemas.xmlsoap.org/wsdl/" xmlns:soap12="http://schemas.xmlsoap.org/wsdl/soap12/" xmlns:wsp="http://schemas.xmlsoap.org/ws/2004/09/policy" xmlns:wsu="http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-utility-1.0.xsd" xmlns:wsaw="http://www.w3.org/2006/05/addressing/wsdl" xmlns:xsd="http://www.w3.org/2001/XMLSchema" xmlns:tns="urn:calc" targetNamespace="urn:calc">
  <wsp:Policy wsu:Id="WSHttpBinding_ICalculator_policy"><wsp:ExactlyOne><wsp:All><wsaw:UsingAddressing/></wsp:All></wsp:ExactlyOne></wsp:Policy>
  <wsdl:types>
    <xsd:schema targetNamespace="urn:calc/import">
      <xsd:import namespace="urn:calc" schemaLocation="/api/Service.svc?xsd=xsd0"/>
    </xsd:schema>
  </wsdl:types>
  <wsdl:message name="ICalculator_Add_InputMessage"><wsdl:part name="parameters" element="tns:Add"/></wsdl:message>
  <wsdl:portType name="ICalculator">
    <wsdl:operation name="Add"><wsdl:input wsaw:Action="urn:calc/ICalculator/Add" message="tns:ICalculator_Add_InputMessage"/></wsdl:operation>
  </wsdl:portType>
  <wsdl:binding name="WSHttpBinding_ICalculator" type="tns:ICalculator">
    <wsp:PolicyReference URI="#WSHttpBinding_ICalculator_policy"/>
    <soap12:binding transport="http://schemas.xmlsoap.org/soap/http"/>
    <wsdl:operation name="Add">
      <soap12:operation soapAction="urn:calc/ICalculator/Add" style="document"/>
      <wsdl:input><soap12:body use="literal"/></wsdl:input>
    </wsdl:operation>
  </wsdl:binding>
</wsdl:definitions>`,
  xsd0: `<xsd:schema xmlns:xsd="http://www.w3.org/2001/XMLSchema" xmlns:tns="urn:calc" targetNamespace="urn:calc" elementFormDefault="qualified">
  <xsd:include schemaLocation="common.xsd"/>
  <xsd:element name="Add"><xsd:complexType><xsd:sequence><xsd:element name="a" type="xsd:int"/><xsd:element name="money" type="tns:Money"/></xsd:sequence></xsd:complexType></xsd:element>
</xsd:schema>`,
  common: `<xsd:schema xmlns:xsd="http://www.w3.org/2001/XMLSchema" elementFormDefault="qualified">
  <xsd:complexType name="Money"><xsd:sequence><xsd:element name="amount" type="xsd:decimal"/></xsd:sequence><xsd:attribute name="currency" type="xsd:string" default="EUR"/></xsd:complexType>
</xsd:schema>`,
};

const splitFiles: Record<string, string> = {
  'https://svc.example.com/api/Service.svc?wsdl=wsdl0': split.defs,
  'https://svc.example.com/api/Service.svc?xsd=xsd0': split.xsd0,
  'https://svc.example.com/api/common.xsd': split.common,
};

describe('WSDL imports', () => {
  it('follows wsdl:import, xsd:import and a chameleon xsd:include', async () => {
    const loaded: string[] = [];
    const sources = await loadWsdlImports(split.root, 'https://svc.example.com/api/Service.svc?wsdl', async url => {
      loaded.push(url);
      if (!(url in splitFiles)) throw new Error('404');
      return splitFiles[url];
    });
    expect(loaded).toEqual(Object.keys(splitFiles));
    const wsdl = parseWsdlDocument(split.root, sources);
    expect(wsdl.unresolvedImports).toBe(0);
    expect(wsdl.operations[0].envelope).toBe(`<?xml version="1.0" encoding="utf-8"?>
<soap:Envelope xmlns:soap="http://www.w3.org/2003/05/soap-envelope" xmlns:i0="urn:calc" xmlns:wsa="http://www.w3.org/2005/08/addressing">
  <soap:Header>
    <wsa:Action soap:mustUnderstand="1">urn:calc/ICalculator/Add</wsa:Action>
    <wsa:To soap:mustUnderstand="1">https://svc.example.com/api/Service12.svc</wsa:To>
  </soap:Header>
  <soap:Body>
    <i0:Add>
      <i0:a>0</i0:a>
      <i0:money currency="EUR">
        <i0:amount>0.0</i0:amount>
      </i0:money>
    </i0:Add>
  </soap:Body>
</soap:Envelope>
`);
  });

  it('follows imports of a schema that was served from another address', async () => {
    const moved: Record<string, string> = {
      ...splitFiles,
      'https://svc.example.com/api/Service.svc?xsd=xsd0': split.xsd0.replace('common.xsd', 'v2/common.xsd'),
    };
    delete moved['https://svc.example.com/api/common.xsd'];
    const loaded: string[] = [];
    const sources = await loadWsdlImports(split.root, 'https://svc.example.com/api/Service.svc?wsdl', async url => {
      loaded.push(url);
      if (url === 'https://svc.example.com/api/Service.svc?xsd=xsd0') return { text: moved[url], url: 'https://svc.example.com/api/schemas/main.xsd' };
      if (url === 'https://svc.example.com/api/schemas/v2/common.xsd') return split.common;
      if (!(url in moved)) throw new Error('404');
      return moved[url];
    });
    expect(loaded).toContain('https://svc.example.com/api/schemas/v2/common.xsd');
    expect(parseWsdlDocument(split.root, sources).unresolvedImports).toBe(0);
  });

  it('explains which import could not be loaded', async () => {
    await expect(loadWsdlImports(split.root, 'https://svc.example.com/api/Service.svc?wsdl', async () => { throw new Error('That URL answered 404.'); }))
      .rejects.toThrow('Kurlo could not load Service.svc?wsdl=wsdl0, which the WSDL imports: That URL answered 404.');
  });

  it('does not let a WSDL from the web read local files', async () => {
    const root = split.root.replace('Service.svc?wsdl=wsdl0', 'file:///etc/passwd');
    await expect(loadWsdlImports(root, 'https://svc.example.com/api/Service.svc?wsdl', async () => '<x/>')).rejects.toThrow('not an http or https address');
  });

  it('builds what it can when imports are missing', () => {
    expect(() => parseWsdlDocument(split.root)).toThrow('files this WSDL imports');
    const partial = parseWsdlDocument(split.root, { base: 'https://svc.example.com/api/Service.svc?wsdl', documents: new Map([['https://svc.example.com/api/Service.svc?wsdl=wsdl0', split.defs]]) });
    expect(partial.unresolvedImports).toBe(1);
    expect(partial.operations[0].envelope).toContain('<i0:Add>?</i0:Add>');
  });

  it('adds no WS-Addressing headers to bindings that do not declare it', () => {
    expect(parseWsdlDocument(calculator).operations.some(operation => operation.envelope.includes('addressing'))).toBe(false);
  });
});
